<script setup>
import DataGrid from './DataGrid.vue';
defineProps({sections:{type:Array,default:()=>[]},loading:Boolean,error:String});
</script>
<template><div class="coverage-review"><p v-if="loading" role="status">Loading Saved Versions…</p><p v-if="error" role="alert">{{error}}</p><p v-if="!sections.length&&!loading" role="status">No Missing Configuration. All Known Items Have Matching Recent Snapshots.</p><details v-for="(section,index) in sections" :key="section.key" :open="index===0" class="coverage-section"><summary>{{section.label}}<span>{{section.rows.length}}</span></summary><DataGrid help="Missing means no captured version; Outdated means the latest applicable item backup is at least seven days old; Changed means current configuration differs. Matching items are hidden."><thead><tr><th>Item</th><th>Namespace</th><th>Coverage</th><th>Latest Applicable Snapshot</th><th>Comparison</th></tr></thead><tbody><tr v-for="row in section.rows" :key="row.id"><td>{{row.name}}</td><td>{{row.namespace||'Global'}}</td><td>{{row.status}}</td><td :data-sort="row.snapshotDate?Date.parse(row.snapshotDate):0">{{row.snapshotDate?new Date(row.snapshotDate).toLocaleString():'None'}}</td><td><details><summary>View Difference</summary><div class="coverage-diff"><article><h3>Current Configuration</h3><pre>{{row.afterText}}</pre></article><article><h3>Latest Saved Version</h3><pre>{{row.beforeText}}</pre></article></div><p v-if="row.missingSecret">Current Secret values were not captured. A reference alone cannot restore credentials.</p></details></td></tr></tbody></DataGrid></details></div></template>
